 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    # The colored field is diagonal-periodic: cell color depends on r+c modulo
    # the cycle length. Infer that cycle robustly from the unmasked interior.
    interior = [
        (r + c, grid[r][c])
        for r in range(3, h)
        for c in range(3, w)
        if grid[r][c] != 0
    ]
    best = None
    for period in range(2, min(15, h + w) + 1):
        by_residue = {}
        for phase in range(period):
            values = [value for diagonal, value in interior if diagonal % period == phase]
            if values:
                counts = Counter(values)
                by_residue[phase] = counts.most_common(1)[0][0]
        errors = sum(by_residue[diagonal % period] != value for diagonal, value in interior)
        # Prefer the shortest period when it explains the data equally well.
        score = (errors / max(1, len(interior)), period)
        if best is None or score < best[0]:
            best = (score, period, by_residue)
    if best is None:
        return [row[:] for row in grid]
    _, period, pattern = best

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if out[r][c] != 0:
                continue
            if r < 2 or c < 2:
                out[r][c] = 1
            elif r == 2 or c == 2:
                out[r][c] = 4
            else:
                out[r][c] = pattern[(r + c) % period]
    return out


