def _best_row_pattern(row):
    """Find a periodic template in the longest clean horizontal run."""
    n = len(row)
    segments = []
    c = 3
    while c < n:
        if row[c] == 0:
            c += 1
            continue
        start = c
        while c < n and row[c] != 0:
            c += 1
        seg = row[start:c]
        if len(seg) >= 4:
            # Fit the smallest repeating period, allowing occasional anomalous
            # cells in the shorter left-hand portions of a row.
            best = None
            for p in range(2, min(12, len(seg) // 2) + 1):
                errs = sum(seg[i] != seg[i % p] for i in range(len(seg)))
                score = (errs, p)
                if best is None or score < best[0]:
                    best = (score, p)
            if best is not None:
                errors, p = best[0][0], best[1]
                # Favor a long run with a clean periodic fit.
                quality = (errors, -len(seg), p)
                segments.append((quality, start, seg, p))
    if not segments:
        return None
    _, start, seg, p = min(segments, key=lambda x: x[0])
    return start, seg[:p], p


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(h):
        pattern = _best_row_pattern(grid[r]) if r >= 3 else None
        for c in range(w):
            if grid[r][c] != 0:
                continue
            # Restore the frame surrounding the patterned field.
            if r < 2 or c < 2:
                out[r][c] = 1
            elif r == 2 or c == 2:
                out[r][c] = 4
            elif pattern is not None:
                start, seq, period = pattern
                out[r][c] = seq[(c - start) % period]
    return out


