def _row_pattern(row):
    """Infer a row's repeating color sequence from all visible cells."""
    observed = [(c, v) for c, v in enumerate(row) if c >= 3 and v != 0]
    if len(observed) < 4:
        return None

    best = None
    for period in range(2, min(12, len(row) // 2) + 1):
        by_residue = {}
        for residue in range(period):
            vals = [v for c, v in observed if c % period == residue]
            if vals:
                by_residue[residue] = Counter(vals).most_common(1)[0][0]
        errors = sum(by_residue[c % period] != v for c, v in observed)
        # A modest complexity penalty favors the true short cycle when a
        # longer period can explain a small sample equally well.
        score = (errors, period)
        if best is None or score < best[0]:
            best = (score, period, by_residue)

    _, period, pattern = best
    return period, pattern


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(h):
        fitted = _row_pattern(grid[r]) if r >= 3 else None
        for c in range(w):
            if grid[r][c] != 0:
                continue
            if r < 2 or c < 2:
                out[r][c] = 1
            elif r == 2 or c == 2:
                out[r][c] = 4
            elif fitted is not None:
                period, pattern = fitted
                out[r][c] = pattern[c % period]
    return out


